import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        V = int(next(iterator))
    except StopIteration:
        return

    adj = []
    for _ in range(V):
        line_parts = []
        while True:
            try:
                val = next(iterator)
                if val.isdigit() or (val.startswith('-') and val[1:].isdigit()):
                    line_parts.append(int(val))
                else:
                    break
            except StopIteration:
                break
        adj.append(line_parts)

    if V == 0:
        print(0)
        return

    degrees = [0] * V
    for u in range(V):
        for v in adj[u]:
            degrees[u] += 1

    odd_degree_count = 0
    for d in degrees:
        if d % 2 != 0:
            odd_degree_count += 1

    def is_connected(start, visited, adj_list):
        queue = deque([start])
        visited[start] = True
        while queue:
            u = queue.popleft()
            for v in adj_list[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

    non_isolated_vertices = [i for i in range(V) if degrees[i] > 0]

    if not non_isolated_vertices:
        if odd_degree_count == 0:
            print(2)
        else:
            print(0)
        return

    start_node = non_isolated_vertices[0]
    visited = [False] * V
    is_connected(start_node, visited, adj)

    connected_component_size = sum(visited)
    if connected_component_size != len(non_isolated_vertices):
        print(0)
        return

    if odd_degree_count == 0:
        print(2)
    elif odd_degree_count == 2:
        print(1)
    else:
        print(0)

if __name__ == "__main__":
    main()
